package com.stitchtrack.controller;
import com.stitchtrack.dao.LaundryDAO;import com.stitchtrack.model.LaundryOrder;import jakarta.servlet.annotation.WebServlet;import jakarta.servlet.http.*;import java.io.*;
@WebServlet("/admin/export.csv") public class ExportCsvServlet extends HttpServlet{private final LaundryDAO dao=new LaundryDAO();protected void doGet(HttpServletRequest r,HttpServletResponse s)throws IOException{s.setContentType("text/csv;charset=UTF-8");s.setHeader("Content-Disposition","attachment; filename=stitchtrack-orders.csv");try(PrintWriter w=s.getWriter()){w.println("Order,Student,Roll,Bag,Items,Status,Stage,Created");for(LaundryOrder o:dao.findAll())w.printf("\"%s\",\"%s\",\"%s\",\"%s\",%d,\"%s\",\"%s\",\"%s\"%n",o.getOrderNumber(),o.getStudentName(),o.getStudentRoll(),o.getBagNumber()==null?"":o.getBagNumber(),o.getTotalItems(),o.getStatus(),o.getCurrentStage(),o.getCreatedAt());}catch(Exception e){s.sendError(500,e.getMessage());}}}
